#!/bin/sh
# Generated by scripts/sync_deploy.py; do not edit.
set -eu
: "${BUILD_NUMBER:?BUILD_NUMBER is required}"
: "${KUBE_CONTEXT:?KUBE_CONTEXT is required}"
case "$BUILD_NUMBER" in ''|[.-]*|*[!A-Za-z0-9_.-]*) echo 'Invalid BUILD_NUMBER' >&2; exit 2 ;; esac
[ "${#BUILD_NUMBER}" -le 128 ]
deploy_dir=$(CDPATH= cd -- "$(dirname "$0")" && pwd)
rendered=$(mktemp -d)
trap 'rm -r "$rendered"' EXIT HUP INT TERM
for resource in deployment.yaml service.yaml ingress.yaml; do
    sed 's/\${TAG}/'"$BUILD_NUMBER"'/g' "$deploy_dir/production/$resource" > "$rendered/$resource"
done
kubectl --context "$KUBE_CONTEXT" apply -f "$rendered"
echo 'applied'
